{
    let &mut Space { ref mut dst, ref mut caps, ref mut matches } =
        self.allocate(matcher)?;
    dst.clear();
    matches.clear();

    // We only want to replace the single match found at `range`,
    // and not any subsequent matches that might occur in the extra
    // look-ahead bytes we sliced onto `subject` above (for
    // multi-line searches). So we find the match ourselves, perform
    // exactly one replacement for it and then copy the remaining
    // bytes up to (but not including) any look-ahead bytes.
    let mut last_match = range.start;
    matcher
        .captures_iter_at(subject, range.start, caps, |caps| {
            let m = caps.get(0).unwrap();
            dst.extend(&subject[last_match..m.start]);
            last_match = m.end;

            let start = dst.len();
            caps.interpolate(
                |name| matcher.capture_index(name),
                subject,
                replacement,
                dst,
            );
            let end = dst.len();
            matches.push(Match::new(start, end));
            false
        })
        .map_err(io::Error::error_message)?;
    dst.extend(&subject[last_match..range.end.min(subject.len())]);
}
Ok(())

