pub fn replace_all<'a>(
    &'a mut self,
    searcher: &Searcher,
    matcher: &M,
    mut subject: &[u8],
    range: std::ops::Range<usize>,
    replacement: &[u8],
) -> io::Result<()> {
    // See the giant comment in 'find_iter_at_in_context' below for why we
    // do this dance.
    let is_multi_line = searcher.multi_line_with_matcher(&matcher);
    if is_multi_line {
        if subject[range.end..].len() >= MAX_LOOK_AHEAD {
            subject = &subject[..range.end + MAX_LOOK_AHEAD];
        }
    } else {
        // When searching a single line, we should remove the line
        // terminator. Otherwise, it's possible for the regex (via
        // look-around) to observe the line terminator and not match
        // because of it.
        let mut m = Match::new(0, range.end);
        trim_line_terminator(searcher, subject, &mut m);
        subject = &subject[..m.end()];
    }
    {
        let &mut Space { ref mut dst, ref mut caps, ref mut matches } =
            self.allocate(matcher)?;
        dst.clear();
        matches.clear();

        // We only want to replace the single match found at `range`,
        // and not any subsequent matches that might occur in the extra
        // look-ahead bytes we sliced onto `subject` above (for
        // multi-line searches). So we find the match ourselves, perform
        // exactly one replacement for it and then copy the remaining
        // bytes up to (but not including) any look-ahead bytes.
        let mut last_match = range.start;
        matcher
            .captures_iter_at(subject, range.start, caps, |caps| {
                let m = caps.get(0).unwrap();
                dst.extend(&subject[last_match..m.start()]);
                last_match = m.end();

                let start = dst.len();
                caps.interpolate(
                    |name| matcher.capture_index(name),
                    subject,
                    replacement,
                    dst,
                );
                let end = dst.len();
                matches.push(Match::new(start, end));
                false
            })
            .map_err(io::Error::error_message)?;

